'use strict';

const { solveInvisibleWidget } = require('../module/widgetSolver');

/**
 * Solve an INVISIBLE Turnstile: the target page is replaced with a local
 * widget page carrying the siteKey, the token is harvested from the
 * hidden cf-response input. Solved fresh on every call.
 */
async function solveTurnstileMin(args) {
    return solveInvisibleWidget({
        ...args,
        template: 'fakePage.html',
        label: 'solveTurnstileMin',
    });
}

module.exports = solveTurnstileMin;
